#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> reverseKSubarrays(std::vector<int>& nums, int k) {
        std::vector<int> res = nums;
        int n = res.size();
        for (int start = 0; start < n; start += k) {
            int l = start, r = std::min(start + k - 1, n - 1);
            while (l < r) {
                std::swap(res[l++], res[r--]);
            }
        }
        return res;
    }
};

class Solution {
    public int[] reverseKSubarrays(int[] nums, int k) {
        int[] res = nums.clone();
        int n = res.length;
        for (int start = 0; start < n; start += k) {
            int l = start, r = Math.min(start + k - 1, n - 1);
            while (l < r) {
                int tmp = res[l];
                res[l] = res[r];
                res[r] = tmp;
                l++;
                r--;
            }
        }
        return res;
    }
}

